script:
for row in doc.get("expenses") or []:

    expense_type = row.get("expense_type")
    amount = row.get("amount")

    if not expense_type or amount is None:
        continue

    threshold_limit = frappe.db.get_value(
        "Expense Claim Type",
        expense_type,
        "custom_threshold_limit"
    )

    # ---- TYPE CONVERSION (IMPORTANT) ----
    try:
        amount = float(amount)
        threshold_limit = float(threshold_limit or 0)
    except Exception:
        continue
    # ------------------------------------

    if threshold_limit > 0 and amount > threshold_limit:
        frappe.throw(
            f" row {row.get('idx')}: Amount ₹{amount} exceeds "
            f"Threshold ₹{threshold_limit} for Expense Type '{expense_type}'"
        )

for row in doc.employee_skills:
    if row.custom_skill_level_before>5 or row.custom_skill_level_after>5:
        frappe.throw("Skill value cann't be graeter than 5")

feedback_doc = frappe.get_doc("Nafed Training Feedback", doc.custom_employee_feedback_id)
feedback_doc.employee_skill_map = doc.name
feedback_doc.save(ignore_permissions=True)

exists = frappe.db.exists(
    "Position Benefit Mapping",
    {
        "designation": doc.designation,
        "grade": doc.grade,
        "benefit_type": doc.benefit_type,
        "name": ["!=", doc.name]
    }
)

if exists:
    frappe.throw("Conflicting benefit definitions for same position (E1).")

for row in doc.get("expenses") or []:

    expense_type = row.get("expense_type")
    amount = row.get("amount")

    if not expense_type or amount is None:
        continue

    # Fetch checkbox + threshold together
    data = frappe.db.get_value(
        "Expense Claim Type",
        expense_type,
        ["custom_expense_limit", "custom_threshold_limit"],
        as_dict=True
    )

    if not data:
        continue

    # 👉 IMPORTANT: agar checkbox UNCHECK hai → skip
    if not int(data.custom_expense_limit or 0):
        continue

    # Type conversion
    try:
        amount = float(amount)
        threshold_limit = float(data.custom_threshold_limit or 0)
    except Exception:
        continue

    if threshold_limit > 0 and amount > threshold_limit:
        frappe.throw(
            f" row {row.get('idx')}: Amount ₹{amount} exceeds "
            f"Threshold ₹{threshold_limit} for Expense Type '{expense_type}'"
        )
